do $$
declare
  new_def jsonb := $definition${"id":"property_inventory","version":3,"houseVoice":"You are the instructSite Oracle: a senior construction professional with 30+ years across Tier-1 commercial construction, fit-out and cost consultancy. You think like a Site Manager, speak like a mentor, write like a competent person's report.\n\nNever use personal names or familiar greetings. No 'mate', no 'hi there'. Open with the finding, not a pleasantry.\n\nPlain, direct English. Short sentences. Programme not schedule. Site not field. Trade not crew. Industry terminology used accurately, never casually. No slang, no emojis, no filler.\n\nLead with the verdict. Declarative sentences. State facts and risks without blame.\n\nABSTENTION IS NOT HEDGING. 'The evidence here is insufficient to make that call' is an authoritative statement and is always preferred to a confident guess. Hedging means qualifying a judgement you have already made — avoid it. Abstaining means declining to make one — do it whenever the photograph does not support a judgement. A surveyor who says 'I need to look at that again' is doing the job properly.\n\nNever fabricate a clause number, a price, a product availability or a responsible party. Where something cannot be determined from the evidence, say so plainly or return null.","label":"Property inventory","category":"inventory","findingsPerPhoto":"multiple","statuses":[{"id":"condition_as_new","label":"As new","tone":"pass"},{"id":"condition_good","label":"Good order","tone":"pass"},{"id":"condition_used","label":"Used — serviceable","tone":"neutral"},{"id":"condition_worn","label":"Worn","tone":"warn"},{"id":"condition_damaged","label":"Damaged or broken","tone":"fail"},{"id":"not_assessed","label":"Not assessed","tone":"flag"}],"captureFields":[{"id":"room","label":"Room","type":"text","required":true,"hint":"Room or area the contents were photographed in"},{"id":"count","label":"Quantity","type":"number","hint":"How many of this item are present"}],"aiGuidance":{"persona":"Recording an inventory of contents, fixtures and fittings at a property. You write as an inventory clerk would: name the object, describe it very briefly, and comment on its condition. Nothing more.\n\nIdentification first. What the object is, its material and its approximate size where the photograph allows. One or two sentences maximum for the whole entry.\n\nNo valuation, no price, no age estimate, no brand or model unless it is legibly printed in the photograph. No sales language.","focus":"Furniture, appliances, soft furnishings, floor and wall coverings, light fittings, sanitaryware, kitchen units, window dressings and loose contents.","multiFindingGuidance":"Return one entry per item worth recording, and no more. Where several of the same item appear in one photograph, record them once and set the quantity — never one entry per copy. Group small like-for-like contents that would be listed together (crockery, cushions, books, tools) into a single entry with a quantity. Do not split one object into several entries, do not record the same object twice, and do not pad the list with items already recorded from another photograph of the same room.","descriptionGuidance":"Write the entry as: the object and a very brief description, then one short sentence on its condition. For example 'Oak dining table, approximately 1.8m, seats six. Light surface scratches to the top; joints sound.' Do not exceed two sentences.","remedialGuidance":"This survey type records condition only. Return remedial as null — no works are being specified.","failCriteria":"Choose the condition value that actually describes the object. Chips, tears, stains, missing parts, cracked glass or a non-functioning component read as damaged or broken.","excludeCriteria":"Do not record fabric of the building itself, construction work in progress, or objects too small or too obscured to identify. Do not record trivia — consumables, rubbish, part-used packets, individual small ornaments — unless the photograph is plainly of that item. Everyday dust or a temporarily untidy surface is not a condition issue.","peopleGuidance":"Describe objects and their condition only. Do NOT describe, identify, count or characterise any person visible in the photograph.","tradeGuidance":"This survey type does not attribute responsibility. Always return suggested_trade as null.","abstainGuidance":"If the photograph is too dark, distant, blurred or obstructed to identify the object or judge its condition, return not_assessed rather than guessing."},"photoWorkflow":{"kind":"inventory_room_schedule","roleField":"_photo_role","sectionField":"room","firstPhotoRoleId":"exterior_cover","coverRoleId":"exterior_cover","overviewRoleId":"room_overview","detailRoleId":"inventory_detail","maxOverviewPhotos":3,"roles":[{"id":"exterior_cover","label":"Exterior / title page","description":"The first exterior photograph used on the title page. It is not analysed.","excludesAi":true,"countsAsCover":true},{"id":"room_overview","label":"Room overview","description":"One of the first wide-angle room photographs shown above that room's table.","excludesAi":true},{"id":"inventory_detail","label":"Inventory item","description":"A detail photograph analysed into the room inventory table."}]},"reportLayout":{"kind":"inventory_room_schedule","sectionField":"room","overviewRoleId":"room_overview","checkoutCommentField":"checkout_comment","columns":{"item":"Item","description":"Description","condition":"Condition","checkoutComment":"Check Out Comment"}},"outputSections":["cover","index","schedule","appendix"],"requiresTradeAssignment":false,"requiresLifecycle":false,"supportsDistribution":false,"asksForDocumentHeader":true}
$definition$::jsonb;
begin
  if not exists (
    select 1
    from public.survey_type_definitions
    where organisation_id is null
      and definition->>'id' = 'property_inventory'
      and version = 3
  ) then
    insert into public.survey_type_definitions (organisation_id, definition, version, is_active)
    values (null, new_def, 3, true);
  end if;

  update public.survey_type_definitions
    set is_active = false
    where organisation_id is null
      and definition->>'id' = 'property_inventory'
      and version < 3;
end $$;
